import json
from pathlib import Path

ROOT=Path('/workspace/github-review')
REPO='Agentic-Trading-Desk'
SHA='4c8c179c5988d6e603c1f3c5f28f93e2344ca225'
tree=json.loads((ROOT/'metadata'/REPO/'tree.json').read_text())['data']['tree']
blobs={e['path']:e['sha'] for e in tree}
def source(path,line,end=None):
    return {'repo':REPO,'ref':'main','commit':SHA,'path':path,'line':line,'end_line':end or line,'blob_sha':blobs.get(path),'local_path':str(ROOT/'repos'/REPO/path)}
def entry(id,title,description,recommendation,refs):
    return {'id':id,'title':title,'description':description,'new_zero_strategy_desk':recommendation,'sources':refs}

patterns=[
 entry('P1','Durable, token-fenced handoff leases','A SQLite BEGIN IMMEDIATE claim moves ARMED work to CLAIMED with a claim token, a two-minute lease, attempt count, expiry and abandoned-lease recovery. Scheduling is deterministic and fair across owner queues.','Adapt to generic tasks, runs and workers with owner-role fairness, renewable lease, cancellation and retry policy; initialize no strategy-owned tasks.',[source('strategy_ledger.py',247,359),source('strategy_ledger.py',386,425)]),
 entry('P2','Persist submission intent before contacting broker','Stable client order IDs, durable SUBMITTING state before POST and UNKNOWN after ambiguous transport preserve the evidence needed to reconcile instead of blindly retrying.','Use a generic broker command/outbox contract with idempotency key and exact payload hash, kept separate from agent outputs.',[source('agentic_runtime.py',726,774),source('strategy_ledger.py',469,499),source('strategy_ledger.py',607,675)]),
 entry('P3','Append-only typed journal and causal links','Journal stores occurrence and recording time, event schema/producer versions, payload hash, source record, correlation/causation IDs and immutable deduplicated events. Correlation links connect evidence, decisions, orders and broker facts.','Reuse the envelope for task creation, worker claims/heartbeats, agent artifacts, accounting events and projections. Keep audit facts distinct from mutable task status.',[source('journal_memory.py',120,289)]),
 entry('P4','Independent stream observation with REST recovery','A dedicated daemon reconnects the paper trade-update socket, records immutable messages, tracks state-transition anomalies and continuity gaps, and invokes REST reconciliation after reconnect.','Keep broker synchronization as an independent supervised service; agents consume projections and cannot silently overwrite broker facts.',[source('shadow_streaming.py',189,248),source('shadow_streaming.py',295,357),source('shadow_streaming.py',376,459)]),
 entry('P5','Failure-isolated background provider refresh','Primary research refresh has at most one live daemon thread, bounds its symbols, waits at least five minutes between starts and reports RUNNING/COMPLETE/ERROR independently of the desk cycle.','Adapt to provider jobs with durable progress and timeout/cancellation; use result artifacts rather than shared mutable in-memory results.',[source('agentic_runtime.py',1306,1328)]),
 entry('P6','Manifest, evidence provenance and resumable checkpoints','ScopePlane stores universe membership/hash, completed-bar cutoffs, evidence/feature hashes, per-symbol scan outcomes, scheduler invocations, leases and next-index checkpoints; JobBudget expresses bounded resources.','Generalize the scope to task input manifests, exact source provenance, quotas and resumable execution with zero market selection rules.',[source('scope_runtime.py',47,100),source('scope_runtime.py',154,192)]),
 entry('P7','Explicit authority and calibrated-status boundaries','Specialist packets carry cited evidence IDs, missing information, expiry, version and explicit shadow-only authority. Brokerage observations separate raw quotes, invalid/stale quotes, spreads, slippage and sample counts.','Use capability/status labels based on actual functions and data; evidence packets can exist before strategies, positions or broker submission are enabled.',[source('m9_specialist_agents.py',27,53),source('m9_specialist_agents.py',118,178),source('brokerage_reality_v2.py',43,114)]),
 entry('P8','Operational state with heartbeat phase and incident/SLO witnesses','The runtime publishes current phase, heartbeat, broker reconciliation, storage, incidents and operator report witnesses instead of exposing only a successful process flag.','Publish a lightweight liveness endpoint immediately, plus worker/task freshness and separate readiness checks; do not require research/strategies to boot.',[source('agentic_runtime.py',502,506),source('agentic_runtime.py',1640,1680),source('operational_command_center.py',219,360)])
]

limitations=[
 entry('O1','Current launcher is a bounded batch, despite resident runtime support','agentic_runtime.py supports a polling daemon and HTTP server, but current persistent_runner.ps1 launches --once. That path calls cycle directly and exits; it does not call run(), which starts the stream supervisor. The watchdog explicitly accepts a completed daily batch without a resident runtime.','Choose explicit service and batch modes. Show the actual scheduler/worker lifecycle in the UI rather than describing all source capabilities as active workers.',[source('agentic_runtime.py',1704,1725),source('agentic_runtime.py',1849,1876),source('persistent_runner.ps1',99,115),source('persistent_watchdog.ps1',89,99)]),
 entry('O2','Named specialists are deterministic packets, not independent reasoning agents','ResearchEngine uses keyword counts; SetupAgents evaluates technical predicates. SpecialistResearchPlane selects evidence by kind, emits template claims, derives uncalibrated confidence from evidence count, and runs six active roles synchronously; technical and liquidity roles are excluded.','Implement real worker run records, task claims, tool invocation/result artifacts and optional model-provider execution. Distinguish scheduled services, deterministic transforms and reasoning workers; do not present templates as completed reasoning.',[source('agentic_runtime.py',201,286),source('m9_specialist_agents.py',118,178),source('m9_specialist_agents.py',181,233),source('m9_specialist_agents.py',252,265)]),
 entry('O3','Strategy-entangled construction prevents a clean empty desk','AgenticDesk unconditionally creates strategy orchestrators, Tensor studies, allocation and experiment planes. app.py also constructs its base Desk on import. agentic_runtime.py constructs AgenticDesk before starting the HTTP listener. The watchdog source documents a cold construction path exceeding ten minutes.','Create a small strategy-free composition root; register optional capabilities explicitly, defer expensive initialization and expose readiness per subsystem. Default strategy registry must be empty.',[source('agentic_runtime.py',288,389),source('agentic_runtime.py',1749,1749),source('app.py',448,448),source('persistent_watchdog.ps1',4,7)]),
 entry('O4','Long synchronous cycle couples broker freshness to unrelated work','Account/orders/snapshots and many research/qualification/ledger/SLO consumers run in one cycle. run() waits cycle_seconds after the entire cycle, so start cadence is cycle duration plus fixed delay. A caught cycle exception updates a shared error state; there is no generic persisted per-agent work queue in this composition.','Use separate broker, market-data, accounting and agent/task workers with independent schedules, budgets, heartbeats and retry/backoff. Store each run and result durably.',[source('agentic_runtime.py',1330,1450),source('agentic_runtime.py',1698,1725)]),
 entry('O5','Order reconciliation has a bounded recent-history window','Alpaca recent_orders asks for at most 500 orders in one response; no pagination or direct lookup by stable client ID is implemented in this adapter. Ledger reconciliation marks absent SUBMITTING/UNKNOWN/AMBIGUOUS local orders unknown.','Page broker history and query unresolved intents directly by client ID; persist cursors and reconciliation coverage. Missing from a limited response must remain distinct from absent at broker.',[source('app.py',172,176),source('strategy_ledger.py',607,625)]),
 entry('O6','Partial-fill closure facts require a redesigned delta model','strategy_lot_closures has a unique exit-client-order/lot pair. Reconciliation subtracts previously recorded closed quantity from cumulative exit fills, then INSERT OR IGNOREs the same pair; a later increased partial fill for the same lot cannot add a second closure or enlarge the first. FIFO ordering also uses mutable updated_at. This is a source-derived accounting concern, not a performed live replay.','Record immutable fill-level execution IDs or cumulative-fill deltas with versions; choose immutable entry order for FIFO and reconcile the union of local and broker positions.',[source('strategy_ledger.py',73,81),source('strategy_ledger.py',562,604),source('strategy_ledger.py',673,678)]),
 entry('O7','Paper accounting is not a complete cash/settlement ledger','The reviewed source keeps quantities, lot closures, account snapshots and brokerage observations with floating-point REALs. Brokerage reality labels fees as an explicit zero placeholder and settlement as not yet calibrated; daily_state exists in app Store but is not the cash/fill source of truth used by RiskGate.','Use a dedicated decimal fill/cash/position journal with fees, realized/unrealized P&L, marks, settlement and reconciliation witnesses; treat broker snapshots as observations rather than journal entries.',[source('app.py',55,74),source('app.py',271,305),source('strategy_ledger.py',53,81),source('brokerage_reality_v2.py',109,114)]),
 entry('O8','Persistence and supervision are platform-specific and partially in memory','Singleton uses ctypes.windll and a Windows local mutex; launch/watchdog uses Windows Scheduled Tasks and a hard-coded bundled runtime path. Provider-thread status and cycle state are in memory; daemon threads are not joined on graceful termination. Journal companion failures can roll back alone while the source event/order still commits, with failure counters kept in memory.','Use portable process/service supervision, durable worker status, bounded shutdown and explicit durable journal repair/backlog. Preserve lightweight single-node operation while leaving storage interfaces replaceable.',[source('agentic_runtime.py',75,105),source('agentic_runtime.py',1306,1328),source('agentic_runtime.py',1704,1725),source('app.py',79,102),source('strategy_ledger.py',98,108),source('persistent_runner.ps1',1,8)])
]

